package android.content;
public class ContentValues { private final java.util.HashMap<String,Object> values=new java.util.HashMap<String,Object>(); public ContentValues() {} public ContentValues(int size) {} public ContentValues(ContentValues o) { values.putAll(o.values); } public void put(String k,String v) { values.put(k,v); } public void put(String k,Integer v) { values.put(k,v); } public void put(String k,Long v) { values.put(k,v); } public void put(String k,Boolean v) { values.put(k,v); } public void put(String k,Float v) { values.put(k,v); } public void put(String k,Double v) { values.put(k,v); } public void put(String k,byte[] v) { values.put(k,v); } public void putNull(String k) { values.put(k,null); } public Object get(String k) { return values.get(k); } public String getAsString(String k) { Object v=get(k); return v==null?null:v.toString(); } public Integer getAsInteger(String k) { Object v=get(k); return v==null?null:Integer.valueOf(v.toString()); } public Long getAsLong(String k) { Object v=get(k); return v==null?null:Long.valueOf(v.toString()); } public boolean containsKey(String k) { return values.containsKey(k); } public int size() { return values.size(); } public void clear() { values.clear(); } public void remove(String k) { values.remove(k); } public java.util.Set<String> keySet() { return values.keySet(); } }
